/**
 * Slack Web API transport that records calls. For evals and tests.
 */
import { plainText } from "../../internal/describe-error.js";
function readableCall(call) {
    if (call.method !== "chat.postMessage" &&
        call.method !== "chat.update" &&
        call.method !== "chat.startStream" &&
        call.method !== "chat.appendStream" &&
        call.method !== "chat.stopStream") {
        return undefined;
    }
    const text = textOf(call.args);
    if (text === "") {
        return undefined;
    }
    return { text, at: call.at, method: call.method };
}
function firstReadableCall(calls) {
    for (const call of calls) {
        const readable = readableCall(call);
        if (readable !== undefined) {
            return readable;
        }
    }
    return undefined;
}
function lastReadableCall(calls) {
    for (let i = calls.length - 1; i >= 0; i--) {
        const call = calls[i];
        if (call === undefined) {
            continue;
        }
        const readable = readableCall(call);
        if (readable !== undefined) {
            return readable;
        }
    }
    return undefined;
}
function textOf(args) {
    if (typeof args.markdown_text === "string" && args.markdown_text !== "") {
        return args.markdown_text;
    }
    if (typeof args.text === "string") {
        return args.text;
    }
    return "";
}
export function createRecordingSlackSink(options = {}) {
    const calls = [];
    let n = 0;
    let releaseHeld;
    const holdAll = options.hold === true;
    const holdMethods = Array.isArray(options.hold) ? new Set(options.hold) : undefined;
    const gated = holdAll || holdMethods !== undefined;
    const gate = gated
        ? new Promise((resolve) => {
            releaseHeld = resolve;
        })
        : Promise.resolve();
    function reply(method, args) {
        if (method === "chat.postMessage") {
            return {
                ok: true,
                ts: `${n}.0`,
                channel: plainText(args.channel) || "C1",
            };
        }
        if (method === "chat.startStream") {
            return {
                ok: true,
                ts: `s${n}.0`,
                channel: plainText(args.channel) || "C1",
            };
        }
        if (method === "files.getUploadURLExternal") {
            return {
                ok: true,
                upload_url: "https://files.example.test/upload",
                file_id: `F${n}`,
            };
        }
        if (method === "files.completeUploadExternal") {
            return { ok: true, files: [] };
        }
        if (method === "users.info") {
            return {
                ok: true,
                user: { id: plainText(args.user) || "U1", team_id: "T1" },
            };
        }
        return { ok: true };
    }
    const transport = {
        kind: "api-transport",
        label: "recording",
        async call(method, args) {
            n += 1;
            const result = reply(method, args);
            const ts = typeof result.ts === "string" ? result.ts : undefined;
            calls.push({ method, args, at: Date.now(), ts });
            if (holdAll || holdMethods?.has(method) === true) {
                await gate;
            }
            return result;
        },
    };
    return {
        transport,
        calls,
        methods: () => calls.map((call) => call.method),
        texts: () => calls
            .filter((call) => readableCall(call) !== undefined)
            .map((call) => textOf(call.args))
            .filter((text) => text !== ""),
        firstReadable: () => firstReadableCall(calls),
        lastReadable: () => lastReadableCall(calls),
        chunks: () => calls.flatMap((call) => {
            const chunks = call.args.chunks;
            return Array.isArray(chunks) ? chunks : [];
        }),
        release: () => {
            if (releaseHeld !== undefined) {
                releaseHeld();
            }
        },
    };
}
